var LOG = new File("/Users/gourav/jl-trailer/trailer/sfx_ae/add_sfx_log.txt"); LOG.open("w");
try {
    var proj = app.project;
    if (!proj.file || proj.file.name.indexOf("Verticals_Justin_Levine_Trailer_v7") !== 0) throw new Error("open project is not the v7 trailer project: " + (proj.file ? proj.file.fsName : "unsaved"));
    var comp = null;
    for (var i = 1; i <= proj.numItems; i++) { var it = proj.item(i); if (it instanceof CompItem && it.name === "Verticals_Justin_Levine_Trailer_v7") comp = it; }
    if (!comp) throw new Error("comp not found");
    app.beginUndoGroup("Add trailer SFX");
    for (var j = comp.numLayers; j >= 1; j--) if (comp.layer(j).name.indexOf("SFX ") === 0) comp.layer(j).remove();
    var folder = null;
    for (var i = 1; i <= proj.numItems; i++) { var it = proj.item(i); if (it instanceof FolderItem && it.name === "SFX") folder = it; }
    if (!folder) folder = proj.items.addFolder("SFX");
    var cache = {};
    for (var i = 1; i <= proj.numItems; i++) { var it = proj.item(i); if (it instanceof FootageItem && it.file && it.parentFolder === folder) cache[it.file.fsName] = it; }
    var added = 0;
    for (var k = CUES.length - 1; k >= 0; k--) {
        var c = CUES[k];
        var item = cache[c.file];
        if (!item) { item = proj.importFile(new ImportOptions(new File(c.file))); item.parentFolder = folder; cache[c.file] = item; }
        var L = comp.layers.add(item);
        L.startTime = c.start;
        L.name = c.name;
        L.label = c.label;
        L.property("ADBE Audio Group").property("ADBE Audio Levels").setValue([c.level, c.level]);
        L.property("ADBE Marker").setValueAtTime(c.t, new MarkerValue(c.name.split("  ").slice(1).join("  ")));
        added++;
    }
    var vid = comp.layer(comp.numLayers); vid.name = "Trailer v7 (picture + voice mix)"; vid.locked = true;
    app.endUndoGroup();
    proj.save();
    LOG.write("OK added " + added + " SFX layers, " + folder.numItems + " files in the SFX folder, comp layers " + comp.numLayers + ", saved " + proj.file.fsName);
} catch (e) { LOG.write("ERR " + e.toString() + " line " + e.line); }
LOG.close();
